    var ratio = topLevel - fLevel;
    var topTexCoord = computeVolumeTextureCoord(texCoord, topLevel);
    var bottomTexCoord = computeVolumeTextureCoord(texCoord, bottomLevel);

    var topVolumeValue = textureSampleLevel(uVolumeTexture, uVolumeTextureSampler, topTexCoord, 0.0);
    var bottomVolumeValue = textureSampleLevel(uVolumeTexture, uVolumeTextureSampler, bottomTexCoord, 0.0);
    var fResult = computeVolumeValue(topVolumeValue, bottomVolumeValue, ratio, noValue);
