	var xOffset1 = topLevel - yOffset1 * S3MVolume.uVolSideBlockCount;
	var texCoordV1 = (texCoord.y * S3MVolume.uVolHeight + yOffset1 * S3MVolume.uVolBlockLength) / S3MVolume.uVolTexLength;
	var texCoordU1 = (texCoord.x * S3MVolume.uVolWidth + xOffset1 * S3MVolume.uVolBlockLength) / S3MVolume.uVolTexLength;
