    // handle very thin volumes
    if (raySteps <= 1.0)
    {
        tColor.a = 1.0 - pow(1.0 - tColor.a, raySteps);
        return tColor;
    }

    tColor.a = 1.0 - pow(1.0 - tColor.a, jitter);
    color = vec4(tColor.rgb * tColor.a, tColor.a);
    posIS += (jitter * stepIS);

